import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';
import './CartPage.css';

const CartPage = () => {
  const { user, updateUserBalance } = useAuth();
  const navigate = useNavigate();
  const [cart, setCart] = useState(null);
  const [loading, setLoading] = useState(true);
  const [checkoutLoading, setCheckoutLoading] = useState(false);

  useEffect(() => {
    if (!user) {
      navigate('/login');
      return;
    }
    loadCart();
  }, [user, navigate]);

  const loadCart = async () => {
    try {
      const response = await api.get('/cart');
      setCart(response.data);
    } catch (error) {
      console.error('Ошибка загрузки корзины:', error);
    } finally {
      setLoading(false);
    }
  };

  const removeFromCart = async (gameId) => {
    try {
      await api.delete(`/cart/remove/${gameId}`);
      loadCart();
    } catch (error) {
      alert(error.response?.data?.message || 'Ошибка удаления');
    }
  };

  const checkout = async () => {
    if (!confirm(`Оформить заказ на ${cart?.totalPrice?.toFixed(2)} ₽?`)) return;

    setCheckoutLoading(true);

    try {
      const response = await api.post('/cart/checkout');
      alert(response.data.message);
      updateUserBalance(response.data.newBalance);
      navigate('/profile');
    } catch (error) {
      alert(error.response?.data?.message || 'Ошибка оформления заказа');
    } finally {
      setCheckoutLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="cart-page">
        <div className="loading">Загрузка корзины...</div>
      </div>
    );
  }

  return (
    <div className="cart-page">
      <div className="cart-container">
        <h1>🛒 Корзина</h1>

        {cart?.items?.length > 0 ? (
          <>
            <div className="cart-items">
              {cart.items.map(item => (
                <div key={item.gameId} className="cart-item">
                  <div className="cart-item-image">
                    <img 
                      src={item.imageUrl?.startsWith('/') 
                        ? `http://localhost:5000${item.imageUrl}` 
                        : item.imageUrl || 'https://via.placeholder.com/100x100'} 
                      alt={item.title}
                      onError={(e) => {
                        e.target.src = 'https://via.placeholder.com/100x100?text=Game';
                      }}
                    />
                  </div>
                  
                  <div className="cart-item-info">
                    <h3>{item.title}</h3>
                    <p className="genre">{item.genre}</p>
                  </div>

                  <div className="cart-item-price">
                    {item.price.toFixed(2)} ₽
                  </div>

                  <button 
                    className="btn-remove"
                    onClick={() => removeFromCart(item.gameId)}
                  >
                    ✕
                  </button>
                </div>
              ))}
            </div>

            <div className="cart-summary">
              <div className="summary-row">
                <span>Товаров:</span>
                <span>{cart.itemsCount}</span>
              </div>
              <div className="summary-row total">
                <span>Итого:</span>
                <span>{cart.totalPrice?.toFixed(2)} ₽</span>
              </div>

              <div className="cart-actions">
                <button 
                  className="btn-continue"
                  onClick={() => navigate('/store')}
                >
                  ← Продолжить покупки
                </button>
                <button 
                  className="btn-checkout"
                  onClick={checkout}
                  disabled={checkoutLoading || user?.balance < cart.totalPrice}
                >
                  {checkoutLoading 
                    ? '⏳ Оформление...' 
                    : user?.balance < cart.totalPrice 
                      ? `❌ Недостаточно средств (нужно ${cart.totalPrice?.toFixed(2)} ₽)`
                      : `💰 Оформить заказ (${cart.totalPrice?.toFixed(2)} ₽)`}
                </button>
              </div>

              {user && (
                <div className="balance-info">
                  Ваш баланс: <strong>{user.balance?.toFixed(2)} ₽</strong>
                  {user.balance < cart.totalPrice && (
                    <button 
                      className="btn-topup-link"
                      onClick={() => navigate('/topup')}
                    >
                      ➕ Пополнить
                    </button>
                  )}
                </div>
              )}
            </div>
          </>
        ) : (
          <div className="cart-empty">
            <div className="empty-icon"></div>
            <h2>Корзина пуста</h2>
            <p>Добавьте игры из магазина</p>
            <button 
              className="btn-go-store"
              onClick={() => navigate('/store')}
            >
              🛒 Перейти в магазин
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default CartPage;
